// Helper type to make all nested string literals into just `string`
type DeepStringify<T> = T extends string
  ? string
  : T extends readonly (infer U)[]
  ? readonly DeepStringify<U>[]
  : T extends object
  ? { readonly [K in keyof T]: DeepStringify<T[K]> }
  : T;

export type TranslationType = DeepStringify<typeof translations.es>;
